func TestSecretCacheTTLAndNegative(t *testing.T) {
	ctx := t.Context()
	c, p, clock := newCache(t, openbao.CacheOptions{TTL: time.Minute, RefreshAheadFactor: 1})
	if _, err := p.Set(ctx, "a", "1", nil); err != nil {
		t.Fatal(err)
	}
	if reveal(t, must(c.Get(ctx, "a", nil))) != "1" {
		t.Fatal("first get")
	}
	_, _ = p.Set(ctx, "a", "2", nil) // behind the cache's back
	if reveal(t, must(c.Get(ctx, "a", nil))) != "1" {
		t.Fatal("cached value expected")
	}
	if v, _ := c.Get(ctx, "missing", nil); v != nil {
		t.Fatal("missing")
	}
	_, _ = p.Set(ctx, "missing", "now", nil)
	if v, _ := c.Get(ctx, "missing", nil); v != nil {
		t.Fatal("negative result must be cached")
	}
	clock.Advance(time.Minute)
	if reveal(t, must(c.Get(ctx, "a", nil))) != "2" {
		t.Fatal("expired entry must be refetched")
	}
	if v, _ := c.Get(ctx, "missing", nil); v == nil {
		t.Fatal("expired negative entry must be refetched")
	}
	s := c.Stats()
	if s.Hits != 2 || s.Misses != 4 || s.Size != 2 || s.Refreshes != 0 {
		t.Fatalf("stats %+v", s)
	}
	p.SetError(openbao.ErrUnavailable)
	if _, err := c.Get(ctx, "other", nil); !errors.Is(err, openbao.ErrUnavailable) {
		t.Fatalf("error passthrough: %v", err)
	}
}

func TestSecretCacheRefreshAheadAndStale(t *testing.T) {
	ctx := t.Context()
	c, p, clock := newCache(t, openbao.CacheOptions{TTL: 10 * time.Second, StaleWhileRevalidate: 5 * time.Second})
	_, _ = p.Set(ctx, "a", "1", nil)
	_ = must(c.Get(ctx, "a", nil))
	_, _ = p.Set(ctx, "a", "2", nil)

	clock.Advance(9 * time.Second) // past ttl*0.8: hit + one background refresh
	if reveal(t, must(c.Get(ctx, "a", nil))) != "1" {
		t.Fatal("refresh-ahead returns the cached value")
	}
	c.Wait()
	if reveal(t, must(c.Get(ctx, "a", nil))) != "2" {
		t.Fatal("background refresh must update the entry")
	}
	_, _ = p.Set(ctx, "a", "3", nil)
	clock.Advance(12 * time.Second) // expired but within stale-while-revalidate
	if reveal(t, must(c.Get(ctx, "a", nil))) != "2" {
		t.Fatal("stale value expected")
	}
	c.Wait()
	if reveal(t, must(c.Get(ctx, "a", nil))) != "3" {
		t.Fatal("revalidated value expected")
	}
	if s := c.Stats(); s.Refreshes != 2 {
		t.Fatalf("refreshes %+v", s)
	}

	// A failing refresh keeps the old value.
	clock.Advance(9 * time.Second)
	p.SetError(openbao.ErrUnavailable)
	_ = must(c.Get(ctx, "a", nil))
	c.Wait()
	p.SetError(nil)
	if reveal(t, must(c.Get(ctx, "a", nil))) != "3" {
		t.Fatal("old value must survive a failed refresh")
	}
}

func TestSecretCacheEvictionAndWrites(t *testing.T) {
	ctx := t.Context()
	c, p, _ := newCache(t, openbao.CacheOptions{MaxEntries: 2})
	for _, n := range []string{"a", "b", "c"} {
		_, _ = p.Set(ctx, n, n, nil)
	}
	_ = must(c.Get(ctx, "a", nil))
	_ = must(c.Get(ctx, "b", nil))
	_ = must(c.Get(ctx, "a", nil)) // a is now most recent
	_ = must(c.Get(ctx, "c", nil)) // evicts b
	if s := c.Stats(); s.Evictions != 1 || s.Size != 2 {
		t.Fatalf("stats %+v", s)
	}
	calls := p.Calls()
	_ = must(c.Get(ctx, "a", nil))
	if p.Calls() != calls {
		t.Fatal("a must still be cached")
	}
	_ = must(c.Get(ctx, "b", nil))
	if p.Calls() == calls {
		t.Fatal("b must have been evicted")
	}

	// Writes pass through and invalidate every version of the name.
	_ = must(c.Get(ctx, "a", &openbao.GetOptions{Version: "1"}))
	if _, err := c.Set(ctx, "a", "a2", nil); err != nil {
		t.Fatal(err)
	}
	if reveal(t, must(c.Get(ctx, "a", nil))) != "a2" {
		t.Fatal("set must invalidate")
	}
	if err := c.Delete(ctx, "a", nil); err != nil {
		t.Fatal(err)
	}
	if v, _ := c.Get(ctx, "a", nil); v != nil {
		t.Fatal("delete must invalidate")
	}
	c.Clear()
	if c.Stats().Size != 0 {
		t.Fatal("clear")
	}
}

func TestSecretCacheReadsAndPassthrough(t *testing.T) {
	ctx := t.Context()
	c, p, _ := newCache(t, openbao.CacheOptions{})
	_, _ = p.Set(ctx, "d/n", "3", nil)
	_, _ = p.Set(ctx, "d/b", "true", nil)
	_, _ = p.Set(ctx, "d/j", `{"k":"v"}`, nil)
	if n, ok, err := c.GetNumber(ctx, "d/n", nil); !ok || err != nil || n != 3 {
		t.Fatal("number")
	}
	if b, ok, err := c.GetBool(ctx, "d/b", nil); !ok || err != nil || !b {
		t.Fatal("bool")
	}
	if s, ok, _ := c.GetString(ctx, "d/n", nil); !ok || s != "3" {
		t.Fatal("string")
	}
	var m map[string]string
	if ok, err := c.GetJSON(ctx, "d/j", &m, nil); !ok || err != nil || m["k"] != "v" {
		t.Fatal("json")
	}
	if _, err := c.Require(ctx, "d/none", nil); !errors.Is(err, openbao.ErrNotFound) {
		t.Fatal("require")
	}
	if ok, _ := c.Exists(ctx, "d/n", nil); !ok {
		t.Fatal("exists")
	}
	if many, _ := c.GetMany(ctx, []string{"d/n", "d/none"}, nil); len(many) != 1 {
		t.Fatal("getMany")
	}
	if all, _ := c.GetAll(ctx, "d"); len(all) != 3 {
		t.Fatal("getAll")
	}
	if list, _ := c.List(ctx, "d"); len(list) != 3 {
		t.Fatal("list")
	}
	if md, _ := c.Metadata(ctx, "d/n", nil); md == nil {
		t.Fatal("metadata")
	}
	const prefix = "GROW_CACHE_TEST_"
	t.Cleanup(func() {
		for _, n := range []string{"N", "B", "J", "MAPPED"} {
			_ = os.Unsetenv(prefix + n)
		}
	})
	if set, err := c.LoadEnv(ctx, "d", &openbao.LoadEnvOptions{Prefix: prefix}); err != nil || len(set) != 3 {
		t.Fatalf("loadEnv %v %v", set, err)
	}
	if set, err := c.LoadEnvMapping(ctx, map[string]string{prefix + "MAPPED": "d/n"}, nil); err != nil || len(set) != 1 {
		t.Fatalf("loadEnvMapping %v %v", set, err)
	}
	changed := make(chan struct{}, 1)
	h := c.Watch(ctx, "d/n", 5*time.Millisecond, func(_, _ *openbao.SecretValue) { changed <- struct{}{} }, nil)
	defer h.Stop()
	time.Sleep(20 * time.Millisecond)
	_, _ = p.Set(ctx, "d/n", "4", nil)
	select {
	case <-changed:
	case <-time.After(5 * time.Second):
		t.Fatal("watch through cache")
	}
	// Defaults apply for nil options and negative SWR.
	if openbao.NewSecretCache(p, nil) == nil || openbao.NewSecretCache(p, &openbao.CacheOptions{StaleWhileRevalidate: -1}) == nil {
		t.Fatal("constructor")
	}
}

